begin;
select no_plan();
create function pg_temp.bundle() returns jsonb language sql as $$select $fixture${"schema":"gina.library-import.v1","package_key":"test-library-intake","revision":1,"previous_hash":null,"title":"Test import package","grade":5,"subject":"Matematik","provenance":{"locale":"tr","curriculum_reference":{"programme_url":"https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/448?kod=MAB3","programme_page_updated":"2026-09-04","checked_on":"2026-11-03","distribution_index":"https://odsgm.meb.gov.tr/www/1donem-konu-soru-dagilim-tablolari-2026-2027/icerik/1724","candidate_scenario_id":"tr-2026-2027-t1-ilkmat2-g5-d6","candidate_source_sha256":"d5429b5962a08adc04acd71ceaae2d517bca507f8b4cf94354bcd55a9670aebf","mapping_status":"proposed_pending_subject_review"},"programme_version":"2026-09-04 web programme; implementation/school applicability pending review","school_track_applicability":"pending_review","assessment_notes":["20 items form a pool, not a 20-question compulsory session or an official school exam.","Questions sharing a source are related observations; do not count them as independent evidence of mastery.","All difficulty labels are estimates; no empirical calibration or official approval.","Schematic drawing/description does not certify compass, ruler or protractor manipulation.","Do not grade drawing neatness, motor control, gender, handwriting style or response speed."],"private_note":"PRIVATE_PROVENANCE_SECRET"},"assets":[{"key":"segments","mime":"image/png","sha256":"890c8dc04fe5952ec0d0af6efac019b10bb3287d116b22adcca2e1bd5effdeb8","width":1,"height":1,"base64":"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGNwcHAAAAGEAMGDX2mUAAAAAElFTkSuQmCC"}],"sources":[{"key":"segments","title":"İki çizim","body":"A ve B arasında iki ucu noktayla gösterilmiş bir çizim; C noktasından başlayıp D üzerinden sağa doğru devam eden, ucunda ok bulunan başka bir çizim var.","alt":"AB çiziminde iki uç nokta var. CD çiziminde başlangıç C; D üzerinden sağa uzanan ok var.","asset_key":"segments","minimum_reading_width":0,"provenance":{"origin":"original_gina_mathematical_diagram","svg_sha256":"a7465f14b876c2ac11a84384c0082f5d16d5fee29cd75b927b8b3c2a1882709b","color_space":"sRGB"}}],"questions":[{"key":"gina-g5-math-geometry-01","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"kolay","stem":"AB ve CD çizimlerinin geometrik adlarını yaz. Uç noktaları ve devam yönleri bakımından aralarındaki farkı açıkla.","choices":[]},"teacher":{"correct_key":null,"expected_answer":"TEACHER_ANSWER_SECRET","solution":"İki uçta nokta bulunan AB sınırlıdır. CD’de başlangıç C ve devamı gösteren bir ok vardır.","explanation":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"AB’yi doğru parçası olarak adlandırır."},{"id":"c2","points":1,"criterion":"CD’yi ışın olarak adlandırır."},{"id":"c3","points":1,"criterion":"AB’nin iki uç noktayla sınırlı olduğunu belirtir."},{"id":"c4","points":1,"criterion":"CD’nin C’den başlayıp D yönünde devam ettiğini belirtir."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"Ok ucunu ikinci uç nokta sanmak.","next_step":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.2","mapping_status":"proposed_pending_subject_review","evidence_scope":"reasoning"},"response":{"mode":"text_or_drawing","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Metin veya anlamı açık etiketli çizim kabul edilir; yazı güzelliği puanlanmaz."},"evidence_unit":"segments","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical","private_note":"PRIVATE_METADATA_SECRET"}},{"key":"gina-g5-math-geometry-02","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"orta","stem":"Defterinde E ve F adlı iki farklı nokta göster. E’den başlayıp F yönünde devam eden bir ışını şematik çiz veya nasıl çizileceğini tarif et. Düz çizgiyi oluşturmak için hangi aracı seçerdin? Neden?","choices":[]},"teacher":{"correct_key":null,"expected_answer":"E başlangıçtır; çizgi F’den geçer ve F yönünde bir okla devam eder. Düz çizgi için cetvel/çizgeç veya dijital ışın aracı seçilir.","solution":"E ve F işaretlenir. Cetvel iki noktaya hizalanır. E’den başlayıp F’den geçen çizgi F yönüne uzatılır; devam yönü okla gösterilir.","explanation":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"E başlangıç noktasını doğru belirler."},{"id":"c2","points":1,"criterion":"Çizgi veya tarif F’den geçer."},{"id":"c3","points":1,"criterion":"Devam yönünü F yönündeki okla veya eşdeğer sözle gösterir."},{"id":"c4","points":1,"criterion":"Cetvel/çizgeç/dijital ışın aracını düz çizgi oluşturma gerekçesiyle seçer."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"E’nin gerisine de ok ekleyerek ışını doğruya çevirmek.","next_step":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.1","mapping_status":"proposed_pending_subject_review","evidence_scope":"tool_selection_and_schematic_representation_not_instrument_performance"},"response":{"mode":"drawing_or_description","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Kalem zorunlu değildir. Çizim istenen soruda şeklin uçlarını, ok yönünü ve bağlantılarını yazıyla açıkça tarif etmek de kabul edilir. Bu alternatif gerçek araç kullanma becerisi kanıtı sayılmaz."},"evidence_unit":"question-02","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical"}}]}$fixture$::jsonb$$;
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000004101','library-review-admin@test.local'),('00000000-0000-4000-8000-000000004102','library-review-parent@test.local'),('00000000-0000-4000-8000-000000004103','library-review-admin2@test.local');
insert into public.admins(user_id) values('00000000-0000-4000-8000-000000004101'),('00000000-0000-4000-8000-000000004103');
create temp table review_package(id uuid); grant all on review_package to authenticated;
create temp table first_review(result jsonb); grant all on first_review to authenticated;
set local role anon;
select throws_ok($$select public.admin_get_library_reviews(gen_random_uuid())$$,'42501',null,'anonymous has no review grant');
reset role;set local role service_role;
select throws_ok($$select public.admin_get_library_reviews(gen_random_uuid())$$,'42501',null,'service role is not an editor');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004102","gina":{"role":"parent"}}',true);
select throws_ok($$select public.admin_get_library_reviews(gen_random_uuid())$$,'42501','forbidden','parent cannot read editorial notes');
select throws_ok($$select public.admin_list_library_draft_packages()$$,'42501','forbidden','parent cannot page drafts');
select throws_ok($$select public.admin_review_library_question(gen_random_uuid(),gen_random_uuid(),'q',1,0,'suitable','')$$,'42501','forbidden','parent cannot review');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004101","gina":{"admin":true}}',true);
insert into review_package select (public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle()||'{"package_key":"test-editorial-review"}')->>'id')::uuid;
select is(public.admin_get_library_reviews((select id from review_package)),'[]'::jsonb,'new package has no inherited approvals');
select throws_ok($$select public.admin_get_library_reviews(gen_random_uuid())$$,'P0001','library_review_not_found','unknown package rejected');
select throws_ok($$select public.admin_review_library_question(gen_random_uuid(),(select id from review_package),'missing',1,0,'suitable','')$$,'P0001','library_review_not_found','unknown question rejected');
select throws_ok($$select public.admin_review_library_question(gen_random_uuid(),(select id from review_package),'gina-g5-math-geometry-01',2,0,'suitable','')$$,'P0001','library_review_question_changed','exact question revision checked');
select throws_ok($$select public.admin_review_library_question(gen_random_uuid(),(select id from review_package),'gina-g5-math-geometry-01',1,0,'publish','')$$,'P0001','library_review_input','review cannot publish');
select throws_ok($$select public.admin_review_library_question(gen_random_uuid(),(select id from review_package),'gina-g5-math-geometry-01',1,0,'changes_requested','  ')$$,'P0001','library_review_input','correction requires a meaningful note');
select throws_ok($$select public.admin_review_library_question(null,(select id from review_package),'gina-g5-math-geometry-01',1,0,'suitable','')$$,'P0001','library_review_input','request id required');
insert into first_review select public.admin_review_library_question('10000000-0000-4000-8000-000000004101',(select id from review_package),'gina-g5-math-geometry-01',1,0,'changes_requested','PRIVATE_EDITOR_NOTE');
select is((select result->>'review_revision' from first_review),'1','first review revision is one');
select is(public.admin_review_library_question('10000000-0000-4000-8000-000000004101',(select id from review_package),'gina-g5-math-geometry-01',1,0,'changes_requested','PRIVATE_EDITOR_NOTE'),(select result from first_review),'exact receipt replay');
select throws_ok($$select public.admin_review_library_question('10000000-0000-4000-8000-000000004101',(select id from review_package),'gina-g5-math-geometry-01',1,0,'suitable','')$$,'P0001','library_review_request_conflict','same request cannot change meaning');
select throws_ok($$select public.admin_review_library_question(gen_random_uuid(),(select id from review_package),'gina-g5-math-geometry-01',1,0,'suitable','')$$,'P0001','library_review_changed','stale editor cannot overwrite');
select is(public.admin_get_library_reviews((select id from review_package))#>>'{0,note}','PRIVATE_EDITOR_NOTE','editor note readback');
select ok(public.admin_get_library_import((select id from review_package),false)::text not like '%PRIVATE_EDITOR_NOTE%','review note absent from student projection');
select is(public.admin_review_library_question(gen_random_uuid(),(select id from review_package),'gina-g5-math-geometry-01',1,1,'suitable','Checked')->>'review_revision','2','explicit next revision accepted');
select is(jsonb_array_length(public.admin_get_library_reviews((select id from review_package))),1,'reader returns latest decision per question');
select is(public.admin_get_library_reviews((select id from review_package))#>>'{0,outcome}','suitable','latest outcome returned');
select is(public.admin_get_library_import((select id from review_package),false)->>'status','draft','suitable does not publish package');
select throws_ok($$select public.admin_list_library_draft_packages(p_limit=>101)$$,'P0001','invalid_input','pagination bounded');
select throws_ok($$select public.admin_list_library_draft_packages(p_before_id=>gen_random_uuid())$$,'P0001','invalid_input','partial cursor rejected');
select is(jsonb_array_length(public.admin_list_library_draft_packages(p_limit=>1)),1,'first page bounded');
select is(jsonb_array_length(public.admin_list_library_draft_packages(p_before_created_at=>(public.admin_list_library_draft_packages(p_limit=>1)->0->>'created_at')::timestamptz,p_before_id=>(public.admin_list_library_draft_packages(p_limit=>1)->0->>'id')::uuid)),0,'cursor excludes last row');
select throws_ok($$select * from gina.library_editorial_reviews$$,'42501',null,'direct private table access denied');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004103","gina":{"admin":true}}',true);
select throws_ok($$select public.admin_review_library_question('10000000-0000-4000-8000-000000004101',(select id from review_package),'gina-g5-math-geometry-01',1,0,'changes_requested','PRIVATE_EDITOR_NOTE')$$,'P0001','library_review_request_conflict','receipt scoped to original editor');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004101","gina":{"admin":true}}',true);
create temp table next_package(id uuid);grant all on next_package to authenticated;
insert into next_package select (public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle()||jsonb_build_object('package_key','test-editorial-review','revision',2,'previous_hash',public.admin_get_library_import((select id from review_package),false)->>'content_hash'))->>'id')::uuid;
select is(public.admin_get_library_reviews((select id from next_package)),'[]'::jsonb,'new package version never inherits approval');
reset role;
select is((select count(*)::int from gina.library_editorial_reviews where package_id=(select id from review_package)),2,'history preserved and replay makes no extra decision');
select is((select count(*)::int from public.audit_log where actor_id='00000000-0000-4000-8000-000000004101' and action='library_question.reviewed'),2,'one audit per actual review');
select ok(not exists(select 1 from public.audit_log where details::text like '%PRIVATE_EDITOR_NOTE%'),'audit excludes private note text');
select throws_ok($$update gina.library_editorial_reviews set note='replace' where package_id=(select id from review_package)$$,'P0001','library_import_immutable','history cannot be overwritten');
delete from public.admins where user_id='00000000-0000-4000-8000-000000004101';
set local role authenticated;
select throws_ok($$select public.admin_get_library_reviews((select id from review_package))$$,'42501','forbidden','revocation blocks reads without token refresh');
select throws_ok($$select public.admin_review_library_question('10000000-0000-4000-8000-000000004101',(select id from review_package),'gina-g5-math-geometry-01',1,0,'changes_requested','PRIVATE_EDITOR_NOTE')$$,'42501','forbidden','revocation blocks replay');
reset role;
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000004101'$$,'editor deletion not blocked');
select * from finish();
rollback;
